"""Extract full text (paragraphs + tables) from the tutorial docx for code review."""
import sys
from docx import Document
from docx.table import Table
from docx.text.paragraph import Paragraph

src = r"C:\Users\UserX\Downloads\光谱仪\AS7343光谱仪制作教程.docx"
out = r"C:\Users\UserX\Downloads\光谱仪\_extracted_tutorial.txt"

doc = Document(src)

def iter_block_items(parent):
    from docx.oxml.ns import qn
    body = parent.element.body
    for child in body.iterchildren():
        if child.tag == qn('w:p'):
            yield Paragraph(child, parent)
        elif child.tag == qn('w:tbl'):
            yield Table(child, parent)

lines = []
for block in iter_block_items(doc):
    if isinstance(block, Paragraph):
        style = block.style.name if block.style is not None else ""
        text = block.text
        # mark code-like paragraphs
        if text.strip():
            if 'Code' in style or '代码' in style or 'HTML Preformatted' in style or '源代码' in style:
                lines.append("[CODE-STYLE] " + text)
            else:
                lines.append(text)
        else:
            lines.append("")
    else:  # Table
        lines.append("=== TABLE START ===")
        for row in block.rows:
            cells = [c.text.replace("\n", " / ") for c in row.cells]
            lines.append(" | ".join(cells))
        lines.append("=== TABLE END ===")

with open(out, "w", encoding="utf-8") as f:
    f.write("\n".join(lines))

print("OK, lines:", len(lines))
"}

