    CH_BLUE_FZ_450NM = 0x00, // Blue peak wavelength 450 nanometers (cycle 1)
    CH_GREEN_FY_555NM,       // Green (wide bandwidth) peak wavelength 555 nanometers (cycle 1)
    CH_ORANGE_FXL_600NM,     // Orange peak wavelength 600 nanometers (cycle 1)
    CH_NIR_855NM,            // NIR peak wavelength 855 nanometers (cycle 1)
    CH_VIS_1,                // VIS (cycle 1)
    CH_FD_1,                 // Flicker Detection (cycle 1)
    CH_DARK_BLUE_F2_425NM,   // Dark Blue peak wavelength 425 nanometers (cycle 2)
    CH_LIGHT_BLUE_F3_475NM,  // Light Blue peak wavelength 475 nanometers (cycle 2)
    CH_BLUE_F4_515NM,        // Blue peak wavelength 515 nanometers (cycle 2)
    CH_BROWN_F6_640NM,       // Brown peak wavelength 640 nanometers (cycle 2)
    CH_VIS_2,                // VIS (cycle 2)

/*
  Using the AMS AS7343 Sensor.

  This example shows how to setup the AS7343 sensor with default settings and
  print out all the spectral data from the sensor.

  By: Pete Lewis
  SparkFun Electronics
  Date: 2025/04/22
  SparkFun code, firmware, and software is released under the MIT License.
    Please see LICENSE.md for further details.

  Hardware Connections:
  IoT RedBoard --> AS7331
  QWIIC --> QWIIC

  Serial.print it out at 115200 baud to serial monitor.

  Feel like supporting our work? Buy a board from SparkFun!
  https://www.sparkfun.com/products/23220
*/

#include <SparkFun_AS7343.h>

SfeAS7343ArdI2C mySensor;

uint16_t myData[ksfAS7343NumChannels]; // Array to hold spectral data

void setup()
{
    Serial.begin(115200);
    while (!Serial)
    {
        delay(100);
    };
    Serial.println("AS7343 Example 02 - All Channels");

    Wire.begin();

    // Initialize sensor and run default setup.
    if (mySensor.begin() == false)
    {
        Serial.println("Sensor failed to begin. Please check your wiring!");
        Serial.println("Halting...");
        while (1)
            ;
    }

    Serial.println("Sensor began.");

    // Power on the device
    if (mySensor.powerOn() == false)
    {
        Serial.println("Failed to power on the device.");
        Serial.println("Halting...");
        while (1)
            ;
    }
    Serial.println("Device powered on.");

    // Set the AutoSmux to output all 18 channels
    if (mySensor.setAutoSmux(AUTOSMUX_18_CHANNELS) == false)
    {
        Serial.println("Failed to set AutoSmux.");
        Serial.println("Halting...");
        while (1)
            ;
    }
    Serial.println("AutoSmux set to 18 channels.");

    // Enable Spectral Measurement
    if (mySensor.enableSpectralMeasurement() == false)
    {
        Serial.println("Failed to enable spectral measurement.");
        Serial.println("Halting...");
        while (1)
            ;
    }
    Serial.println("Spectral measurement enabled.");
}

void loop()
{
    mySensor.ledOn();
    delay(100);

    // Read all data registers
    // if it fails, print a failure message and continue
    if (mySensor.readSpectraDataFromSensor() == false)
    {
        Serial.println("Failed to read spectral data.");
    }

    mySensor.ledOff();

    // Get the data from the sensor (all channels)
    // Note, we are using AutoSmux set to 18 channels
    // and the data will be written to the myData array
    // The size of the array is defined in the header file
    // This method returns the number of channels read
    int channelsRead = mySensor.getData(myData);

    // Print the data from all the channels that were read
    for (int channel = 0; channel < channelsRead; channel++)
    {
        Serial.print(myData[channel]);
        Serial.print(",");
    }

    Serial.println();

    delay(500);
}

