/* ============ 基础 I2C 读写 ============ */

HAL_StatusTypeDef AS7343_ReadReg(I2C_HandleTypeDef *hi2c, uint8_t reg, uint8_t *val)
{
    /* 用 HAL_I2C_Mem_Read，自动处理"发寄存器地址→重启→读数据"流程 */
    /* datasheet 9.3：读事务 = START, CHIP-ADDR-W, REG-ADDR, RESTART, CHIP-ADDR-R, DATA, STOP */
    return HAL_I2C_Mem_Read(hi2c, AS7343_I2C_ADDR, reg,
                            I2C_MEMADD_SIZE_8BIT, val, 1, 100);
}

HAL_StatusTypeDef AS7343_WriteReg(I2C_HandleTypeDef *hi2c, uint8_t reg, uint8_t val)
{
    /* datasheet 9.2：写事务 = START, CHIP-ADDR-W, REG-ADDR, DATA, STOP */
    return HAL_I2C_Mem_Write(hi2c, AS7343_I2C_ADDR, reg,
                              I2C_MEMADD_SIZE_8BIT, &val, 1, 100);
}

HAL_StatusTypeDef AS7343_ReadMulti(I2C_HandleTypeDef *hi2c, uint8_t reg, uint8_t *buf, uint16_t len)
{
    /* datasheet 9：寄存器地址自动递增，burst read */
    return HAL_I2C_Mem_Read(hi2c, AS7343_I2C_ADDR, reg,
                            I2C_MEMADD_SIZE_8BIT, buf, len, 200);
}

/* ============ Bank 切换 ============ */

HAL_StatusTypeDef AS7343_SetBank(I2C_HandleTypeDef *hi2c, uint8_t bank)
{
    /* datasheet 10.2.8 CFG0 (0xBF)：
       REG_BANK=0 → 访问 0x80+ 寄存器
       REG_BANK=1 → 访问 0x20-0x7F 寄存器
       CFG0 本身始终可访问（bank 切换寄存器）*/
    uint8_t cfg0;
    if (AS7343_ReadReg(hi2c, AS7343_REG_CFG0, &cfg0) != HAL_OK) {
        return HAL_ERROR;
    }
    if (bank) {
        cfg0 |= AS7343_CFG0_REG_BANK;
    } else {
        cfg0 &= ~AS7343_CFG0_REG_BANK;
    }
    return AS7343_WriteReg(hi2c, AS7343_REG_CFG0, cfg0);
}

/* ============ 读 ID ============ */

HAL_StatusTypeDef AS7343_ReadID(I2C_HandleTypeDef *hi2c, uint8_t *id)
{
    /* ID 寄存器在 0x5A（Bank 1），期望值 0x81 */
    /* datasheet 10.2.4：ID Register (Address 0x5A), Default 10000001 */
    HAL_StatusTypeDef ret;
    if (AS7343_SetBank(hi2c, 1) != HAL_OK) {
        return HAL_ERROR;
    }
    ret = AS7343_ReadReg(hi2c, AS7343_REG_ID, id);
    AS7343_SetBank(hi2c, 0);  /* 切回 Bank 0，即使读失败也要切回 */
    return ret;
}

/* ============ 初始化 ============ */

HAL_StatusTypeDef AS7343_Init(I2C_HandleTypeDef *hi2c)
{
    HAL_StatusTypeDef ret;
    uint8_t enable;
    uint32_t timeout;

    /* 1. 切到 Bank 0 */
    if (AS7343_SetBank(hi2c, 0) != HAL_OK) {
        return HAL_ERROR;
    }

    /* 2. 上电：PON=1 */
    /* datasheet 10.2.1：先设 PON=1，再配置其他寄存器 */
    ret = AS7343_WriteReg(hi2c, AS7343_REG_ENABLE, AS7343_ENABLE_PON);
    if (ret != HAL_OK) {
        return HAL_ERROR;
    }

    /* 3. 等待初始化完成 */
    /* datasheet 8：上电后约 300µs 设备初始化，期间 STATUS4 的 INIT_BUSY=1 */
    HAL_Delay(1);  /* 等待 1ms，足够 */

    /* 4. 设置默认积分时间和增益 */
    /* datasheet 10.2.2：
       积分时间 TINT = (ATIME+1) × (ASTEP+1) × 2.78µs
       选 ATIME=100, ASTEP=999 → TINT = 101 × 1000 × 2.78µs = 280.78ms
       ADC 满量程 = 101 × 1000 = 101000，但上限 65535 */
    if (AS7343_SetIntegrationTime(hi2c, 100, 999) != HAL_OK) {
        return HAL_ERROR;
    }

    /* 5. 设置增益 */
    /* datasheet 10.2.3：AGAIN 默认 9（256x）。
       反射式测量信号较强，建议 128x 或 256x */
    if (AS7343_SetGain(hi2c, AS7343_GAIN_256X) != HAL_OK) {
        return HAL_ERROR;
    }

    /* 6. 初始化 SMUX（从 ROM 加载默认配置）*/
    if (AS7343_InitSMUX(hi2c) != HAL_OK) {
        return HAL_ERROR;
    }

    /* 7. 设置 auto_smux=3（18 通道全通道模式）*/
    /* datasheet 10.2.8 CFG20：
       auto_smux=3 → 3 个 cycle，18 个数据寄存器
       Cycle 1: FZ, FY, FXL, NIR, 2xVIS, FD
       Cycle 2: F2, F3, F4, F6, 2xVIS, FD
       Cycle 3: F1, F7, F8, F5, 2xVIS, FD */
    uint8_t cfg20;
    if (AS7343_ReadReg(hi2c, AS7343_REG_CFG20, &cfg20) != HAL_OK) {
        return HAL_ERROR;
    }
    cfg20 = (cfg20 & 0x9FU) | AS7343_CFG20_SMUX_18CH;  /* 清 bits 6:5，设为 3 */
    if (AS7343_WriteReg(hi2c, AS7343_REG_CFG20, cfg20) != HAL_OK) {
        return HAL_ERROR;
    }

    /* 8. 设置自动零补偿频率 */
    /* datasheet 10.2.3 AZ_CONFIG (0xDE)：
       AZ_NTH_ITERATION=255 → 仅在第一次测量前做一次自动零 */
    if (AS7343_WriteReg(hi2c, AS7343_REG_AZ_CONFIG, 255) != HAL_OK) {
        return HAL_ERROR;
    }

    return HAL_OK;
}

/* ============ 设置增益 ============ */

HAL_StatusTypeDef AS7343_SetGain(I2C_HandleTypeDef *hi2c, as7343_gain_t gain)
{
    /* datasheet 10.2.3：CFG1 (0xC6)，AGAIN 在 bits 4:0 */
    if (gain > 12) {
        return HAL_ERROR;
    }
    return AS7343_WriteReg(hi2c, AS7343_REG_CFG1, (uint8_t)gain);
}

/* ============ 设置积分时间 ============ */

HAL_StatusTypeDef AS7343_SetIntegrationTime(I2C_HandleTypeDef *hi2c, uint8_t atime, uint16_t astep)
{
    /* datasheet 10.2.2：
       ATIME (0x81)：8-bit，1-255
       ASTEP (0xD4/0xD5)：16-bit，1-65534
       TINT = (ATIME+1) × (ASTEP+1) × 2.78µs
       注意：ATIME 和 ASTEP 都不能为 0 */
    if (atime == 0 && astep == 0) {
        return HAL_ERROR;
    }
    if (AS7343_WriteReg(hi2c, AS7343_REG_ATIME, atime) != HAL_OK) {
        return HAL_ERROR;
    }
    /* ASTEP 低字节先写，高字节后写（16-bit 寄存器锁存规则）*/
    /* datasheet 9：16-bit 字段先写低字节再写高字节 */
    if (AS7343_WriteReg(hi2c, AS7343_REG_ASTEP_L, (uint8_t)(astep & 0xFFU)) != HAL_OK) {
        return HAL_ERROR;
    }
    if (AS7343_WriteReg(hi2c, AS7343_REG_ASTEP_H, (uint8_t)((astep >> 8) & 0xFFU)) != HAL_OK) {
        return HAL_ERROR;
    }
    return HAL_OK;
}

/* ============ SMUX 初始化 ============ */

HAL_StatusTypeDef AS7343_InitSMUX(I2C_HandleTypeDef *hi2c)
{
    /* datasheet 10.2.8：
       CFG6 (0xF5) SMUX_CMD 在 bits 4:3
       ENABLE (0x80) SMUXEN 在 bit4，触发后自动清除 */
    uint8_t cfg6;
    uint8_t enable;
    uint32_t timeout;

    /* 设置 SMUX_CMD=0（ROM 初始化）*/
    if (AS7343_ReadReg(hi2c, AS7343_REG_CFG6, &cfg6) != HAL_OK) {
        return HAL_ERROR;
    }
    cfg6 = (cfg6 & ~0x18U) | (AS7343_SMUX_CMD_ROM_INIT << 3U);
    if (AS7343_WriteReg(hi2c, AS7343_REG_CFG6, cfg6) != HAL_OK) {
        return HAL_ERROR;
    }

