#include <stdio.h>
#include <string.h>
/* USER CODE END Includes */

/* USER CODE BEGIN PV */
extern I2C_HandleTypeDef hi2c1;
extern UART_HandleTypeDef huart1;

#define LED_CTRL_Pin GPIO_PIN_0
#define LED_CTRL_Port GPIOB

as7343_data_t sensor_data;
uint8_t device_id = 0;
char tx_buf[256];
/* USER CODE END PV */

/* USER CODE BEGIN PRT */
/* LED 控制：低电平点亮，高电平熄灭 */
#define LED_ON()   HAL_GPIO_WritePin(LED_CTRL_Port, LED_CTRL_Pin, GPIO_PIN_RESET)
#define LED_OFF()  HAL_GPIO_WritePin(LED_CTRL_Port, LED_CTRL_Pin, GPIO_PIN_SET)

/* 串口打印 */
void uart_print(const char *fmt, ...)
{
    va_list args;
    va_start(args, fmt);
    int len = vsnprintf(tx_buf, sizeof(tx_buf), fmt, args);
    va_end(args);
    if (len > 0) {
        HAL_UART_Transmit(&huart1, (uint8_t *)tx_buf, len, 100);
    }
}
/* USER CODE END PRT */

int main(void)
{
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_I2C1_Init();
    MX_USART1_UART_Init();

    /* USER CODE BEGIN 2 */
    /* 上电先熄灭 LED */
