    dark_offset[8]  = dark.f6;
    dark_offset[9]  = dark.f7;
    dark_offset[10] = dark.f8;
    dark_offset[11] = dark.nir;
}

/* === 8.2 白参考校准（原文）=== */
float white_ref[12] = {0};

void calibrate_white(void)
{
    as7343_data_t white;
    LED_ON();
    HAL_Delay(10);
    AS7343_StartMeasurement(&hi2c1);
    while (!AS7343_IsDataReady(&hi2c1)) HAL_Delay(5);
    AS7343_ReadData(&hi2c1, &white);
    LED_OFF();

    white_ref[0]  = (float)white.f1  - dark_offset[0];
    white_ref[1]  = (float)white.f2  - dark_offset[1];
    white_ref[2]  = (float)white.fz  - dark_offset[2];
    white_ref[3]  = (float)white.f3  - dark_offset[3];
    white_ref[4]  = (float)white.f4  - dark_offset[4];
    white_ref[5]  = (float)white.fy  - dark_offset[5];
    white_ref[6]  = (float)white.f5  - dark_offset[6];
    white_ref[7]  = (float)white.fxl - dark_offset[7];
    white_ref[8]  = (float)white.f6  - dark_offset[8];
    white_ref[9]  = (float)white.f7  - dark_offset[9];
    white_ref[10] = (float)white.f8  - dark_offset[10];
    white_ref[11] = (float)white.nir - dark_offset[11];
}

/* === 8.3 反射率计算（原文）=== */
float get_reflectance(uint16_t raw, int channel)
{
    float corrected = (float)raw - dark_offset[channel];
    if (white_ref[channel] > 0) {
        return corrected / white_ref[channel];
    }
    return 0;
}
