< /* ============ 基础 I2C 读写 ============ */
< 
< HAL_StatusTypeDef AS7343_ReadReg(I2C_HandleTypeDef *hi2c, uint8_t reg, uint8_t *val)
< {
<     /* 用 HAL_I2C_Mem_Read，自动处理"发寄存器地址→重启→读数据"流程 */
<     /* datasheet 9.3：读事务 = START, CHIP-ADDR-W, REG-ADDR, RESTART, CHIP-ADDR-R, DATA, STOP */
<     return HAL_I2C_Mem_Read(hi2c, AS7343_I2C_ADDR, reg,
<                             I2C_MEMADD_SIZE_8BIT, val, 1, 100);
< }
< 
< HAL_StatusTypeDef AS7343_WriteReg(I2C_HandleTypeDef *hi2c, uint8_t reg, uint8_t val)
< {
<     /* datasheet 9.2：写事务 = START, CHIP-ADDR-W, REG-ADDR, DATA, STOP */
<     return HAL_I2C_Mem_Write(hi2c, AS7343_I2C_ADDR, reg,
<                               I2C_MEMADD_SIZE_8BIT, &val, 1, 100);
< }
< 
< HAL_StatusTypeDef AS7343_ReadMulti(I2C_HandleTypeDef *hi2c, uint8_t reg, uint8_t *buf, uint16_t len)
< {
<     /* datasheet 9：寄存器地址自动递增，burst read */
<     return HAL_I2C_Mem_Read(hi2c, AS7343_I2C_ADDR, reg,
<                             I2C_MEMADD_SIZE_8BIT, buf, len, 200);
< }
< 
< /* ============ Bank 切换 ============ */
< 
< HAL_StatusTypeDef AS7343_SetBank(I2C_HandleTypeDef *hi2c, uint8_t bank)
< {
<     /* datasheet 10.2.8 CFG0 (0xBF)：
<        REG_BANK=0 → 访问 0x80+ 寄存器
<        REG_BANK=1 → 访问 0x20-0x7F 寄存器
<        CFG0 本身始终可访问（bank 切换寄存器）*/
<     uint8_t cfg0;
<     if (AS7343_ReadReg(hi2c, AS7343_REG_CFG0, &cfg0) != HAL_OK) {
<         return HAL_ERROR;
<     }
<     if (bank) {
<         cfg0 |= AS7343_CFG0_REG_BANK;
<     } else {
<         cfg0 &= ~AS7343_CFG0_REG_BANK;
<     }
<     return AS7343_WriteReg(hi2c, AS7343_REG_CFG0, cfg0);
< }
< 
< /* ============ 读 ID ============ */
< 
< HAL_StatusTypeDef AS7343_ReadID(I2C_HandleTypeDef *hi2c, uint8_t *id)
< {
<     /* ID 寄存器在 0x5A（Bank 1），期望值 0x81 */
