# 设计参考（开源光谱仪的通用做法）:
#   · Public Lab Spectral Workbench —— 暗帧扣除 + 白参考归一化得相对反射率
#   · Adafruit AS7341 库 calculateBasicCounts() —— raw 除以 (增益x积分时间) 归一化
#   · 教程第八章: 反射率 = (raw - 暗场) / (白参考 - 暗场)
# 固件增益/积分时间固定(256x/281ms)，因此 PC 端做相对校准即可; 若以后改了
# 固件的 AGAIN/ATIME，需要重新采一次白参考。
class Calib:
    def __init__(self, path):
        self.path = path
        self.dark = None      # list[12] 原始 counts
        self.white = None     # list[12] 原始 counts
        self.load()

    def ready(self):
        return self.dark is not None and self.white is not None

    def capture_dark(self, raws):
        if raws:
            self.dark = list(np.mean(np.array(list(raws)[-5:]), axis=0))  # 最近5帧均值

    def capture_white(self, raws):
        if raws:
            self.white = list(np.mean(np.array(list(raws)[-5:]), axis=0))

    def clear(self):
        self.dark = None
        self.white = None
        self.save()

    def reflectance(self, vals):
        d = np.array(self.dark, dtype=float)
        w = np.array(self.white, dtype=float)
        denom = w - d
        safe = np.where(np.abs(denom) < 1e-6, np.nan, denom)   # 白≈黑的通道置 NaN
        r = (np.asarray(vals, dtype=float) - d) / safe * 100.0
        r = np.nan_to_num(r, nan=0.0, posinf=0.0, neginf=0.0)
        return np.clip(r, -5.0, 150.0)                          # 显示稳定用

    def save(self):
        data = {'dark': self.dark, 'white': self.white,
                'created': time.strftime('%Y-%m-%d %H:%M:%S')}
        try:
            with open(self.path, 'w', encoding='utf-8') as f:
                json.dump(data, f, ensure_ascii=False, indent=1)
        except OSError as e:
            print('校准保存失败: %r' % e)

    def load(self):
        if not os.path.exists(self.path):
            return
        try:
            with open(self.path, encoding='utf-8') as f:
                data = json.load(f)
            if isinstance(data.get('dark'), list) and len(data['dark']) == 12:
                self.dark = [float(v) for v in data['dark']]
            if isinstance(data.get('white'), list) and len(data['white']) == 12:
                self.white = [float(v) for v in data['white']]
            if self.dark is not None or self.white is not None:
                print('已加载校准文件 %s' % self.path)
        except Exception as e:
            print('校准文件读取失败（忽略）: %r' % e)

    def status_text(self, show_raw=False):
        if self.dark is None and self.white is None:
            return '未校准：显示原始 ADC'
        if not self.ready():
            return '已采暗场，等白参考：显示原始 ADC'
        return '已校准：显示反射率 %' if not show_raw else '已校准：当前显示原始 ADC'


